tasks = { ["Find Commander Folkar"] = [===[Знайти командира Фолкара]===] },
},
[95314] = { en="That Shadowvale Green Elixir", ai=true,
[===[Той зелений еліксир Тінедолу]===],
[===[До навали Скари відлюдне селище Тінеділ славилося своїм шепітливим еліксиром. Його переганяли з трав, що ростуть лише в Гибелі Тіра, і цей еліксир шукали аптекарі, містики й отруйники, навіть після того, як його заборонили в місті.

До мене зверталося чимало покупців, яким кортить роздобути трохи еліксиру. Вирушай до руїн Тінедолу в глибині Шепітливого лісу на заході. Я готова запропонувати чималу винагороду, якщо ти знайдеш для мене кілька пляшок.]===],
[===[Зберіть 8 пляшок шепітливого еліксиру в Тінедолі, а потім поверніться до Каролаї Аніс у Брілль.]===],
[===[Сподіваюся, ти не {стать:заблукав:заблукала}?]===],
[===[Кажеш, у Тінедолі оселилося зло? Мушу визнати, мене це не дивує. Лісовий люд був дивакуватий і не любив гостей. Дехто вважає, що сам Шепітливий ліс проклятий, а еліксир, перегнаний з його коріння, несе в собі те саме прокляття...

...але досить забобонів і чуток, {ім'я:к}. Дякую за еліксири. Ось, візьми це як плату.]===],
},
[95328] = { en="Whispering Horror Residue", ai=true,
[===[Залишок шепітливого страховища]===],
[===[Всупереч здоровому глузду ви зішкрібаєте й збираєте рештки тварюки, які ще звиваються. Комусь у Підмісті вони можуть знадобитися.]===],
[===[Доставте залишок шепітливого страховища отцю Ланкестеру в квартал Війни в Підмісті.]===],
[===[Маєш щось для мене, {клас:к}?]===],
[===[Який цікавий зразок. Кажеш, з-під Шепітливого лісу? Ні для кого не секрет, що того мерзенного місця торкнулася Порожнеча.

Я радо скористаюся нагодою дослідити таємниці тіні, {клас:к}. Дозволь мені заплатити тобі за знахідку.]===],
},
[95349] = { en="The Earthen Ring", ai=true,
[===[Служителі Землі]===],
[===[Нещодавні події з культом затримали мої плани вирушити до Азероту, тож я мушу на якийсь час залишитися тут, у Валанаарі. Натомість нашим авангардом станеш ти та ще кілька Вітротворців. Алаана Бурехід зустріне наших Вітротворців, коли ті прибудуть до Мулґору, і я раджу тобі дослідити Азерот, поки ми завершуємо свої справи тут. Незабаром ми до вас приєднаємося.

Коли будеш {стать:готовий:готова}, прошу, йди до причалу просто біля цієї оселі й сідай там на корабель-неборіз.

Бану-Алаг, {ім'я:к}.]===],
[===[Вирушайте кораблем-неборізом з острова Зефрас до Мулґору і, прибувши, поговоріть з Алааною Бурехід.]===],
nil,
[===[Бачу, ще шукачі пригод із Зефрасу. Чудово. Вітри, безперечно, нам сприяють! Нам знадобиться час, щоб облаштуватися тут, тож ти можеш присвятити трохи часу дослідженню цієї нової землі.

Азерот - захопливий новий світ, але й небезпечний. Тобі варто підготуватися до цієї нової пригоди, ознайомившись із довколишніми землями.]===],
},
[95350] = { en="Welcome to Azeroth", ai=true,
[===[Ласкаво просимо до Азероту]===],
[===[Світ тут, унизу, великий, і наші нові союзники — запорука нашого виживання.

Служителі Землі входять до "Орди" — гордої спільноти однодумних народів. Розташоване неподалік місто Громовий Бескид є частиною Орди, а далі на схід лежить її столиця, Орґріммар.

Знайди майстра польотів у центрі Громового Бескиду. Звідти тебе доправлять до Орґріммара, де ти від імені Вітротворців встановиш зв'язок із воєвождем Орди — Траллом. Хай вітри ведуть тебе, {ім'я:к}.]===],
[===[Вирушайте до Орґріммара та поговоріть з Траллом у долині Мудрості.]===],
nil,
[===[Лок-тар, {клас:к}. Я Тралл, воєвождь Орди.

Посланець Служителів Землі попередив мене, що слід чекати когось із Вітротворців, — і ось ти тут. Не думав я, що побачу перед собою {стать:вищого ельфа:вищу ельфу} тут, в Орґріммарі, але Орда все одно прийме тебе як свого гостя.

Маєш моє благословення подорожувати землями Орди. Іди з честю, {стать:Вітротворче:Вітротворко}.]===],
},
[95417] = { en="The Purple Ones", ai=true,
[===[Фіолетові]===],
[===[Клишопал бачить — друзі йдуть. Деякі не вертаються. Деякі вертаються фіолетові. То дивно. Фіолетові більше не як друзі.

Куди інші йдуть? Чого не вертаються? Клишопалу аж думати треба.

Ти сильно бити. Може, ти піти шукати друзів у печері? Може, ти пофіолетовієш. То теж дивно.]===],
[===[Знайдіть для Клишопала зниклих огрів у печерах під Сонячною галявиною.]===],
nil,
[===[<Огр лежить мертвий у колі темних рун. Схоже, він не витримав сили ритуалу Сутінкового Молота.>]===],
},
[95418] = { en="Spread the Word", ai=true,
[===[Рознеси звістку]===],
[===[Мені досить Сутінкових. Клишопал тепер вільний огр.

Я йти шукати Дуболупа. Він найнайбільший огр, якого Клишопал бачити. Він покинути Сутінкових. Забрати з собою багато друзів. Тепер черга Клишопала. Я йти до вільних огрів. Вони йти в пагорби. Клишопал сумувати за пагорбами. Більше не трощити каміння. Може, ти колись прийти?

Я сидіти тут, поки все не вщухне. Ти віднести голови Чоґ'Зака друзям. Ну. Може, одну голову. Мені теж одну. Чесний обмін.]===],
[===[Доставте голову Чоґґа Тран'ґулу в Роґ'мар.]===],
[===[Отже, Сутінковий Молот щось знайшов у землі? Вигнати це зло було правильно, {ім'я:к}. Якщо воно цікавить тих фанатиків, довіряти йому не можна.]===],
[===[Так-так. Схоже, та печера була не єдиною несподіванкою.

Тобі вдалося переконати одного з огрів Сутінкового Молота перейти на наш бік? І він згадав про інших таких, як він? Треба негайно діяти.]===],
},
[95420] = { en="Land of Giants", ai=true,
[===[Край велетнів]===],
[===[Очевидно, ці непокірні огри зовсім не друзі Сутінковому Молоту. Ми, орки, маємо славну історію боротьби пліч-о-пліч з ограми, і, можливо, настав час знову згадати про ті давні союзи. А ця голова може стати ключем.

Надходять звістки, що в пагорбах далеко на півночі помітили огрів. Якщо вірити цьому Клишопалу, саме там і живе їхній клан. Вирушай до їхньої твердині й піднеси цей трофей на знак нашої дружби. Якщо пощастить, вони вислухають твою пропозицію, перш ніж розчавлять тебе.]===],
[===[Доставте голову Чоґґа до міста огрів на півночі.]===],
[===[<Величезний огр відригує вам просто в обличчя.>

Що крихітна істота принести Дуболупу?]===],
[===[Ти розтрощити Чоґ'Зака? Мала істота показати силу.

Що ти хотіти від Дуболупа?]===],
},
[95424] = { en="Might Makes Right", ai=true,
[===[Хто сильніший, той і правий]===],
[===[Тут огри шанувати силу і кров.

Слабаки піти з Валун'ока. Вернутися до Сутінкового Молота.

Ти {стать:невеликий:невелика}. Може, {стать:сильний:сильна}. Покажи Дуболупу силу і розтрощ слабких огрів. Якщо крихітна істота змогти.]===],
[===[Вбийте 7 сутінкових молотобійців і 7 сутінкових вогнезовів для Дуболупа у Валун'оку.]===],
nil,
[===[{стать:Крихітний:Крихітна} {раса:н} показати силу. Земля здригатися від смерті Сутінкового Молота. Я звідси відчувати!]===],
},
[95425] = { en="Unworthy Champion", ai=true,
[===[Негідний чемпіон]===],
[===[Гупало колись бути найкращий чемпіон Дуболупа. Він сильний. Я дати Гупалу могутню зброю.

Але Дуболуп помилятися. Гупало слабкий, як інші. Він покинути Валун'ок. Вернутися до Сутінкового Молота. Забрати огрів із собою в печеру на схід, біля води. Забрати могутню зброю з собою!

Це зброя Дуболупа! Розтрощити Гупалу череп і забрати назад Черепотрощ. Він нічий не чемпіон!]===],
[===[Заберіть у Гупала череполом для Дуболупа з Валун'ока.]===],
[===[Чого ти хотіти? Нести Черепотрощ зараз!]===],
[===[Черепотрощ належати справжньому огру. Колись Дуболуп обрати нового чемпіона.]===],
},
[95427] = { en="Twilight No More!", ai=true,
[===[Кінець Сутінковим!]===],
[===[Друзі Клишопала... мертві? Чому?

Це вина Чоґ'Зака! Вони казати, шо зробити огрів сильними! Вони брехати!!

Більше не трощити каміння! Маленька істота допомогти Клишопалу трощити дурні голови Чоґ'Зака!]===],
[===[Вбийте Чоґ'Зака в печері Сонячної галявини й зберіть його голови для Клишопала.]===],
[===[Більше не вбивати друзів! Чоґ'Зак сьогодні вмерти!]===],
[===[{стать:Малий:Мала} {раса:н} вбити Чоґ'Зака?



Клишопал більше не трощити каміння для малявок! Клишопал більше не втрачати друзів! Я більше не Сутінковий Молот!]===],
},
[95428] = { en="Clugfist's Decree", ai=true,
[===[Указ Дуболупа]===],
[===[{стать:Малий:Мала} {раса:н} добре трощити Сутінкових. Може, твоя Орда сильніша, ніж Дуболуп думати.

Ти можеш лишатися у Валун'оку. Поки що.

Сказати іншим малявкам: ми скоро знову пускати кров.]===],
[===[Доповідайте Кром'рошу в Роґ'марі.]===],
nil,
[===[Повстання огрів? І так скоро після їхньої власної боротьби за свободу від Сутінкового Молота? Історія цих воїнів майже така ж кривава, як і наша. Вони стануть могутніми союзниками, якщо ми й надалі здобуватимемо їхню довіру.

Ти добре {стать:впорався:впоралася}, {ім'я:к}. Підозрюю, що це лише початок наших стосунків з кланом Валун'ок.]===],
},
[95431] = { en="Rumblings of Discontent", ai=true,
[===[Рокіт невдоволення]===],
[===[Я стежу за пересуваннями нашого ворога, і мені вдалося виявити слабкість у їхніх лавах. Огри-дисиденти почали бунтувати, прагнучи такої ж свободи, як їхні родичі з Валун'ока. Чутки про твої звершення поширилися. Ми мусимо цим скористатися.

На моїх очах воїн з Валун'ока подався до печер на захід звідси, шукаючи своїх братів і сестер. Знайди його і долучися до його зусиль згуртувати свій народ.]===],
[===[Пошукайте огра з Валун'ока в печері неподалік.]===],
nil,
[===[<Краґ'роґ заносить булаву для удару, але тут придивляється до вас уважніше.>

Стривай... Краґ'роґ знати тебе. Ти битися за Дуболупа!]===],
},
[95432] = { en="Rise Up!", ai=true,
[===[Повстаньте!]===],
[===[Коли Краґ'роґ чути, що {стать:малий:мала} {раса:н} звільняти огрів, Краґ'роґ теж хотіти звільнити огрів.

Тепер тут {стать:малий:мала} {клас:н}, ми разом трощити Сутінкових. Ламати їм кістки. Змусити їх верещати. Звільнити огрів! А потім встигнути додому на рагу.]===],
[===[Завербуйте 5 огрів-шахтарів.]===],
nil,
[===[Ми звільнити багато огрів. Це добре. Ми вбити слабких, боягузливих огрів. Це краще.

Лишитися тільки один огр-боягуз.]===],
tasks = { ["Ogre Miners recruited"] = [===[Огрів-шахтарів завербовано]===] },
},
[95433] = { en="Death to the Executioner", ai=true,
[===[Смерть катові]===],
[===[Коли Дуболуп покидати Сутінкових, один огр стати на шляху. Морґ.

Морґ — величезний огр. Майже такий величезний, як Дуболуп. Але не найвеличезніший. Йому треба малявки, щоб його захищати. Дуболуп так і не мати чесного бою. Тепер МИ не битися чесно.

Знайти Морґа. Привести з собою багато малявок. Вбити його. Принести булаву назад Дуболупу. Тоді Сутінкові знати, що більше не кидати нам виклик!]===],
[===[Заберіть катівську булаву в ката Морґа в Сутінковому савані й принесіть її Дуболупу до Валун'ока.]===],
[===[Краґ'роґ казати, ти битися разом з ним. Що ти принести могутньому Дуболупу?]===],
[===[Морґ мертвий! {стать:Малий:Мала} {раса:н} мати багато хитрощів. Ти подобатися Дуболупу.

Сутінковий Молот розсипатися під силою Валун'ок. Ми звільнити огрів!]===],
},
[95454] = { en="The Honor of the Kor'kron", ai=true,
[===[Честь Кор'крону]===],
[===[Мою робочу руку, якою я тримаю сокиру, зламано, а більшість моїх добірних бійців загинули. Честь Кор'крону тепер у твоїх руках.

Нас послали сюди забрати в'язня, та не абиякого... Ми прийшли по короля Штормовію, Варіана Рінна. Ми перехопили відомості, що його тримають тут, і наш воєвождь наказав доставити його до Орґріммара живим. А присутність чорних драконів... усе ускладнює.

Прошу тебе, рушай далі й знайди Рінна. Я чекатиму тут, поки ти його шукатимеш.]===],
[===[Розшукайте короля Варіана Рінна у в'язниці Альказ.]===],
nil,
nil,
tasks = {
["Find Varian Wrynn"] = [===[Знайти Варіана Рінна]===],
["Read the note on the ground"] = [===[Прочитати записку на землі]===],
},
},
[95483] = { en="Thrall Needs to Know", ai=true,
[===[Тралл має знати]===],
[===[Тралл має знати, що тут сталося. Я зустрінуся з Улкою і подбаю, щоб він міг витримати дорогу, перш ніж повертатися до Орґріммара, тож довіряю тобі передати ці відомості воєвождю замість мене.

Іди ж, солдате Орди. Розкажи нашому воєвождю, яка доля спіткала Варіана Рінна.]===],
[===[Повідомте Траллу в Орґріммарі про долю Варіана Рінна.]===],
nil,
nil,
